struct Node;

/// Truncate `s` to at most `max` bytes, respecting UTF-8 char boundaries.
fn clamp_bytes(mut s: String, max: usize) -> String {
    if s.len() > max {
        let mut end = max;
        while end > 0 && !s.is_char_boundary(end) {
            end -= 1;
        }
        s.truncate(end);
    }
    s
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let inner = query.query;

        // ensures len(question) <= 512 (the requires already guarantees this on
        // input, but we enforce it on output so the postcondition holds by
        // construction regardless of upstream).
        let question = clamp_bytes(inner.question, 512);

        // The node's sole authority: read-only lookup against the
        // 'knowledge-base' store. No other interface is imported.
        let mut knowledge = crate::aap::caps::kb_read::lookup(&question);

        // ensures present(knowledge): the list must be non-empty. If the store
        // returned nothing, supply a single explicit "no results" entry so the
        // postcondition holds.
        if knowledge.is_empty() {
            knowledge.push(String::from("(no knowledge-base entries found)"));
        }

        ConversationContext {
            intent: inner.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
